<template><div class="message-page"><div class="head"><div><h2>消息中心</h2><p>查看审核结果、批次通知和催报提醒</p></div><el-button v-if="messages.some(m=>!m.read)" @click="readAll">全部已读</el-button></div><el-empty v-if="!messages.length" description="暂无消息"/><div v-else class="list"><div v-for="item in messages" :key="item.id" class="item" :class="{unread:!item.read}" @click="open(item)"><div class="dot"></div><div><strong>{{item.title}}</strong><p>{{item.content}}</p><span>{{format(item.createdAt)}}</span></div><el-icon><ArrowRight/></el-icon></div></div></div></template>
<script setup>import{ref,onMounted}from'vue';import{useRouter}from'vue-router';import api from'../../utils/request';const router=useRouter(),messages=ref([]);async function load(){messages.value=(await api.get('/counselor/notifications')).data}onMounted(load);async function open(item){if(!item.read)await api.put(`/counselor/notifications/${item.id}/read`);if(item.targetPath)router.push(item.targetPath);else load()}async function readAll(){await api.put('/counselor/notifications/read-all');load()}function format(v){return v?String(v).replace('T',' ').slice(0,16):''}</script>
<style scoped>.message-page{max-width:900px;margin:auto}.head{display:flex;justify-content:space-between;align-items:center}.head h2{margin:0}.head p{color:#909399}.list{border-top:1px solid #ebeef5}.item{display:grid;grid-template-columns:10px 1fr 24px;gap:12px;align-items:center;padding:18px 8px;border-bottom:1px solid #ebeef5;cursor:pointer}.item.unread{background:#f0f7ff}.dot{width:8px;height:8px;border-radius:50%;background:#dcdfe6}.unread .dot{background:#409eff}.item p{margin:6px 0;color:#606266}.item span{font-size:12px;color:#909399}</style>
